import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Link, Navigate, useSearchParams } from "react-router-dom";
import {
  Activity,
  AlertTriangle,
  ArrowUpRight,
  Bell,
  CheckCircle2,
  ClipboardList,
  Clock,
  DollarSign,
  ExternalLink,
  FolderTree,
  LayoutDashboard,
  LogOut,
  Menu,
  MessageSquare,
  Package,
  Search,
  Settings as SettingsIcon,
  ShieldCheck,
  ShoppingBag,
  ShoppingCart,
  Tag,
  Terminal,
  TrendingDown,
  TrendingUp,
  UserPlus,
  Users,
  XCircle
} from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { useTheme } from "./ThemeContext";
import { apiFetch } from "./api";
import { CATEGORY_LABELS } from "./catalog";
import { formatGhc } from "./money";
import { h, f } from "./h";
import {
  Badge,
  Button,
  Field,
  GlassCard,
  GlassPanel,
  InlineNotice,
  LogoMark,
  SelectInput,
  TextArea,
  TextInput,
  ThemeToggleButton
} from "./ui";

const ORDER_STATUS_OPTS = [
  "pending_payment",
  "awaiting_vendor_payment",
  "paid",
  "processing",
  "sent_for_delivery",
  "delivered",
  "cancelled"
];

const REFUND_OPTS = ["none", "requested", "refunded"];

const REPORT_CATS = {
  fake_seller: "Fake / misleading seller",
  scam: "Scam",
  bad_product: "Bad product / listing",
  chat_abuse: "Abuse in messages",
  other: "Other"
};

const REPORT_STATUS_OPTS = [
  { v: "", l: "All" },
  { v: "open", l: "Open" },
  { v: "in_review", l: "In review" },
  { v: "resolved", l: "Resolved" },
  { v: "dismissed", l: "Dismissed" }
];

const CATEGORY_COLORS = {
  electronics: "#6366f1",
  books: "#ec4899",
  clothing: "#f59e0b",
  food: "#10b981",
  footwears: "#22d3ee",
  other: "#94a3b8"
};

function humanizeOrderStatus(s) {
  return String(s || "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function formatListingStatus(s) {
  if (s === "pending_approval") return "Pending";
  if (s === "active") return "Live";
  if (s === "rejected") return "Rejected";
  if (s === "draft") return "Draft";
  return s || "—";
}

function listingStatusTone(s) {
  if (s === "active") return "success";
  if (s === "pending_approval") return "warn";
  if (s === "rejected") return "danger";
  if (s === "draft") return "warn";
  return "neutral";
}

function relTime(iso) {
  if (!iso) return "";
  const then = new Date(iso).getTime();
  if (!Number.isFinite(then)) return "";
  const s = Math.max(0, Math.round((Date.now() - then) / 1000));
  if (s < 60) return `${s}s ago`;
  const m = Math.round(s / 60);
  if (m < 60) return `${m} min${m === 1 ? "" : "s"} ago`;
  const hr = Math.round(m / 60);
  if (hr < 24) return `${hr} hr${hr === 1 ? "" : "s"} ago`;
  const d = Math.round(hr / 24);
  return `${d} day${d === 1 ? "" : "s"} ago`;
}

const TABS = [
  { id: "dashboard", label: "Dashboard", Icon: LayoutDashboard },
  { id: "users", label: "Users", Icon: Users },
  { id: "listings", label: "Listings", Icon: Package },
  { id: "orders", label: "Orders", Icon: ShoppingCart },
  { id: "payments", label: "Payments & Payouts", Icon: DollarSign },
  { id: "reports", label: "Reports & Complaints", Icon: AlertTriangle },
  { id: "messages", label: "Messages", Icon: MessageSquare },
  { id: "categories", label: "Categories", Icon: FolderTree },
  { id: "settings", label: "Settings", Icon: SettingsIcon },
  { id: "logs", label: "System Logs", Icon: Terminal }
];

function tabTitle(id) {
  const t = TABS.find((x) => x.id === id);
  return t ? t.label : "Dashboard";
}

function tabSubtitle(id) {
  const map = {
    dashboard: "Overview of your marketplace",
    users: "Manage buyers, sellers and admins",
    listings: "Approve, edit and moderate products",
    orders: "Track orders, disputes and refunds",
    payments: "Commission, revenue and seller proceeds",
    reports: "Review user-submitted complaints",
    messages: "Oversight for buyer–seller chats",
    categories: "Catalog breakdown by category",
    settings: "Commission, payments and policy",
    logs: "Recent activity across the platform"
  };
  return map[id] || "";
}

function StatCard({ label, value, sub, Icon, tone = "sky", growthPct = null }) {
  const tones = {
    sky: "bg-sky-500/15 text-sky-500 dark:text-sky-300",
    emerald: "bg-emerald-500/15 text-emerald-500 dark:text-emerald-300",
    amber: "bg-amber-500/15 text-amber-600 dark:text-amber-300",
    cyan: "bg-cyan-500/15 text-cyan-500 dark:text-cyan-300",
    violet: "bg-violet-500/15 text-violet-500 dark:text-violet-300",
    rose: "bg-rose-500/15 text-rose-500 dark:text-rose-300"
  };
  const hasGrowth = growthPct !== null && growthPct !== undefined && Number.isFinite(Number(growthPct));
  const up = hasGrowth && Number(growthPct) >= 0;
