            up ? "bg-emerald-500/15 text-emerald-500" : "bg-rose-500/15 text-rose-500"
          }`
        },
        [
          h(up ? TrendingUp : TrendingDown, { key: "ti", className: "h-3 w-3" }),
          `${up ? "+" : ""}${Number(growthPct).toFixed(1)}%`
        ]
      )
