          className: `flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl ${tones[tone] || tones.sky}`
        },
        Icon ? h(Icon, { className: "h-5 w-5" }) : null
      ),
      h("div", { key: "txt", className: "min-w-0 flex-1" }, [
        h("p", { key: "l", className: "text-xs font-medium uppercase tracking-wide text-slate-500 dark:text-slate-400" }, label),
        h("div", { key: "vrow", className: "mt-1 flex items-center" }, [
          h("p", { key: "v", className: "font-display text-2xl font-bold leading-none text-slate-900 dark:text-white" }, value),
          growthBadge
        ]),
        sub ? h("p", { key: "s", className: "mt-1 truncate text-xs text-slate-500 dark:text-slate-400" }, sub) : null
      ])
    ])
  ]);
}

function OrdersLineChart({ series }) {
  const pts = Array.isArray(series) ? series : [];
  if (pts.length === 0) {
    return h("div", { className: "flex h-56 items-center justify-center text-sm text-slate-500" }, "No order activity yet.");
  }
  const w = 560;
  const svgH = 220;
  const padL = 40;
  const padR = 16;
  const padT = 18;
  const padB = 28;
  const innerW = w - padL - padR;
  const innerH = svgH - padT - padB;
  const counts = pts.map((d) => Number(d.count) || 0);
  const max = Math.max(...counts, 1);
  const step = pts.length > 1 ? innerW / (pts.length - 1) : 0;
  const coords = pts.map((d, i) => ({
    x: padL + i * step,
    y: padT + innerH * (1 - (Number(d.count) || 0) / max)
  }));
  const linePath = coords
    .map((p, i) => {
      if (i === 0) return `M ${p.x} ${p.y}`;
      const prev = coords[i - 1];
      const cx = (prev.x + p.x) / 2;
      return `Q ${prev.x} ${prev.y} ${cx} ${(prev.y + p.y) / 2} T ${p.x} ${p.y}`;
    })
    .join(" ");
  const areaPath = `${linePath} L ${coords[coords.length - 1].x} ${padT + innerH} L ${coords[0].x} ${padT + innerH} Z`;
  const tickStep = Math.max(1, Math.ceil(pts.length / 5));
  const yTicks = [0, 0.5, 1].map((t) => ({ y: padT + innerH * (1 - t), lab: String(Math.round(max * t)) }));
  return h("svg", { viewBox: `0 0 ${w} ${svgH}`, className: "h-56 w-full", preserveAspectRatio: "xMidYMid meet", role: "img", "aria-label": "Orders overview chart" }, [
    h("defs", { key: "defs" }, [
      h("linearGradient", { key: "g", id: "adminOrdersFill", x1: "0%", y1: "0%", x2: "0%", y2: "100%" }, [
        h("stop", { offset: "0%", stopColor: "#8b5cf6", stopOpacity: 0.45 }),
        h("stop", { offset: "100%", stopColor: "#8b5cf6", stopOpacity: 0 })
      ])
    ]),
    ...yTicks.map((tk, i) =>
      h("g", { key: `yt-${i}` }, [
        h("line", { x1: padL, x2: w - padR, y1: tk.y, y2: tk.y, stroke: "rgba(148,163,184,0.22)", strokeDasharray: "3 4", strokeWidth: 1 }),
        h("text", { x: padL - 6, y: tk.y + 4, fontSize: 10, fill: "rgb(148 163 184)", textAnchor: "end", className: "font-mono" }, tk.lab)
      ])
    ),
    h("path", { key: "area", d: areaPath, fill: "url(#adminOrdersFill)", stroke: "none" }),
    h("path", { key: "line", d: linePath, fill: "none", stroke: "#8b5cf6", strokeWidth: 2.4, strokeLinecap: "round", strokeLinejoin: "round" }),
    ...coords.map((p, i) => h("circle", { key: `c-${i}`, cx: p.x, cy: p.y, r: i === coords.length - 1 ? 4 : 2.5, fill: "#8b5cf6", stroke: "white", strokeWidth: 1.2 })),
    ...pts.map((d, i) =>
      i % tickStep === 0 || i === pts.length - 1
        ? h(
            "text",
            { key: `xl-${i}`, x: coords[i].x, y: svgH - 8, fontSize: 10, fill: "rgb(148 163 184)", textAnchor: "middle", className: "font-mono" },
            String(d.date || "").slice(5)
          )
        : null
    )
  ]);
}

function DonutChart({ segments, total }) {
  const size = 200;
  const cx = size / 2;
  const cy = size / 2;
  const r = 72;
  const strokeW = 26;
  const tot = total || segments.reduce((s, x) => s + (Number(x.value) || 0), 0) || 1;
  const circ = 2 * Math.PI * r;
  let offset = 0;
  return h("svg", { viewBox: `0 0 ${size} ${size}`, className: "h-44 w-44" }, [
    h("circle", { key: "bg", cx, cy, r, fill: "none", stroke: "rgba(148,163,184,0.15)", strokeWidth: strokeW }),
    ...segments.map((seg, i) => {
      const frac = (Number(seg.value) || 0) / tot;
      const len = circ * frac;
      const dash = `${len} ${circ - len}`;
      const dashOffset = -offset;
      offset += len;
      return h("circle", {
        key: `s-${i}`,
        cx,
        cy,
        r,
        fill: "none",
        stroke: seg.color,
        strokeWidth: strokeW,
        strokeDasharray: dash,
        strokeDashoffset: dashOffset,
        strokeLinecap: "butt",
        transform: `rotate(-90 ${cx} ${cy})`
      });
    }),
    h("text", { key: "tc", x: cx, y: cy - 4, textAnchor: "middle", className: "fill-slate-900 dark:fill-white font-display", fontSize: 22, fontWeight: 700 }, String(tot)),
    h("text", { key: "tl", x: cx, y: cy + 14, textAnchor: "middle", className: "fill-slate-500", fontSize: 11 }, "Listings")
  ]);
}

function activityForDashboard(dash) {
  const items = [];
  (dash?.recent?.signups || []).forEach((u) => {
    items.push({
      key: `s-${u.id}`,
      at: u.createdAt,
      Icon: UserPlus,
      tone: "bg-sky-500/15 text-sky-400",
      title: "New user registered",
      text: `${u.displayName || u.email || "A new member"} joined as a ${u.role}`
    });
  });
  (dash?.recent?.listings || []).forEach((p) => {
    items.push({
      key: `l-${p.id}`,
      at: p.createdAt,
      Icon: Package,
      tone: p.status === "pending_approval" ? "bg-amber-500/15 text-amber-400" : p.status === "active" ? "bg-emerald-500/15 text-emerald-400" : "bg-rose-500/15 text-rose-400",
      title: p.status === "pending_approval" ? "New listing submitted" : `Listing ${formatListingStatus(p.status)}`,
      text: `${p.name} by ${p.sellerLabel || "seller"}`
    });
  });
  (dash?.recent?.orders || []).forEach((o) => {
    items.push({
      key: `o-${o.id}`,
      at: o.createdAt,
      Icon: ShoppingBag,
      tone: "bg-violet-500/15 text-violet-400",
      title: "Order placed",
      text: `Order #${String(o.id).slice(-6)} ${o.total != null ? `· ${formatGhc(o.total)}` : ""} · ${humanizeOrderStatus(o.status)}`
    });
  });
  items.sort((a, b) => new Date(b.at || 0).getTime() - new Date(a.at || 0).getTime());
  return items.slice(0, 8);
}

export function AdminPage() {
  const { user, accessToken, logout } = useAuth();
  const { confirm, alert, toast } = useNotice();
  const { dark, toggle: toggleTheme } = useTheme();
  const [searchParams, setSearchParams] = useSearchParams();
  const tab = searchParams.get("tab") || "dashboard";
  const setTab = (id) => {
    if (id === "dashboard") setSearchParams({}, { replace: true });
    else setSearchParams({ tab: id }, { replace: true });
    setSidebarOpen(false);
  };

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [headerSearch, setHeaderSearch] = useState("");
  const [appliedSearch, setAppliedSearch] = useState("");

  const [err, setErr] = useState("");
  const [dashboard, setDashboard] = useState(null);
  const [categoriesStat, setCategoriesStat] = useState([]);
  const [users, setUsers] = useState([]);
  const [usersPage, setUsersPage] = useState(1);
  const [usersTotal, setUsersTotal] = useState(0);
  const [usersLimit] = useState(25);
  const [userRole, setUserRole] = useState("all");
  const [userStatus, setUserStatus] = useState("all");
  const [listings, setListings] = useState([]);
  const [listingsPage, setListingsPage] = useState(1);
  const [listingsTotal, setListingsTotal] = useState(0);
  const [listingsLimit] = useState(20);
  const [listFilter, setListFilter] = useState("pending_approval");
  const [orders, setOrders] = useState([]);
  const [ordersPage, setOrdersPage] = useState(1);
  const [ordersTotal, setOrdersTotal] = useState(0);
  const [ordersLimit] = useState(25);
  const [revenue, setRevenue] = useState(null);
  const [revDays, setRevDays] = useState(30);
  const [dashRange, setDashRange] = useState(30);
  const [dashSeries, setDashSeries] = useState(null);
  const [balances, setBalances] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [convPage, setConvPage] = useState(1);
  const [convTotal, setConvTotal] = useState(0);
  const [convLimit] = useState(20);
  const [selectedThreadId, setSelectedThreadId] = useState(null);
  const [threadDetail, setThreadDetail] = useState(null);
  const [reports, setReports] = useState([]);
  const [reportPage, setReportPage] = useState(1);
  const [reportTotal, setReportTotal] = useState(0);
  const [reportStatusFilter, setReportStatusFilter] = useState("");
  const [reportLimit] = useState(25);
  const [settings, setSettings] = useState(null);
  const [settingsForm, setSettingsForm] = useState({
    commissionPercent: 7,
    momoEnabled: true,
    stripeEnabled: true,
    bankEnabled: true,
    listingPolicyNote: ""
  });
  const [savingSettings, setSavingSettings] = useState(false);
  const [systemLog, setSystemLog] = useState([]);
  const [loading, setLoading] = useState(true);

  const [rejectId, setRejectId] = useState(null);
  const [rejectReason, setRejectReason] = useState("");

  const [userSummary, setUserSummary] = useState(null);
  const [resetUserId, setResetUserId] = useState(null);
  const [resetPassword, setResetPassword] = useState("");

  const [moderateOrder, setModerateOrder] = useState(null);
  const [ordStatus, setOrdStatus] = useState("");
  const [ordDispute, setOrdDispute] = useState(false);
  const [ordNote, setOrdNote] = useState("");
  const [ordRefund, setOrdRefund] = useState("none");

  const [editList, setEditList] = useState(null);
  const [editPrice, setEditPrice] = useState("");

  const auth = useMemo(() => ({ headers: { Authorization: `Bearer ${accessToken}` } }), [accessToken]);

  const loadDashboard = useCallback(() => {
    if (!accessToken) return;
    return Promise.all([
      apiFetch("/api/admin/dashboard", auth).then((d) => setDashboard(d)),
      apiFetch("/api/admin/categories", auth).then((d) => setCategoriesStat(d.categories || [])),
      apiFetch(`/api/admin/revenue?days=${dashRange}`, auth).then((d) => setDashSeries(d))
    ]).then(() => undefined);
  }, [accessToken, auth, dashRange]);

  const loadUsers = useCallback(() => {
    if (!accessToken) return;
    const qs = new URLSearchParams({ page: String(usersPage), limit: String(usersLimit) });
    if (appliedSearch) qs.set("q", appliedSearch);
    if (userRole && userRole !== "all") qs.set("role", userRole);
    if (userStatus && userStatus !== "all") qs.set("accountStatus", userStatus);
    return apiFetch(`/api/admin/users?${qs.toString()}`, auth).then((d) => {
      setUsers(d.users || []);
      setUsersTotal(d.total || 0);
    });
  }, [accessToken, usersPage, usersLimit, appliedSearch, userRole, userStatus, auth]);

  const loadListings = useCallback(() => {
    if (!accessToken) return;
    const qs = new URLSearchParams({ status: listFilter === "all" ? "all" : listFilter, page: String(listingsPage), limit: String(listingsLimit) });
    if (appliedSearch) qs.set("q", appliedSearch);
    return apiFetch(`/api/admin/products?${qs.toString()}`, auth).then((d) => {
      setListings(d.products || []);
      setListingsTotal(d.total || 0);
    });
  }, [accessToken, listFilter, listingsPage, listingsLimit, appliedSearch, auth]);

  const loadOrders = useCallback(() => {
    if (!accessToken) return;
    return apiFetch(`/api/admin/orders?page=${ordersPage}&limit=${ordersLimit}`, auth).then((d) => {
      setOrders(d.orders || []);
      setOrdersTotal(d.total || 0);
    });
  }, [accessToken, ordersPage, ordersLimit, auth]);

  const loadRevenue = useCallback(() => {
    if (!accessToken) return;
    return apiFetch(`/api/admin/revenue?days=${revDays}`, auth).then((d) => setRevenue(d));
  }, [accessToken, revDays, auth]);

  const loadBalances = useCallback(() => {
    if (!accessToken) return;
    return apiFetch("/api/admin/sellers/balances", auth).then((d) => setBalances(d.sellers || []));
  }, [accessToken, auth]);

  const loadConversations = useCallback(() => {
    if (!accessToken) return;
    return apiFetch(`/api/admin/conversations?page=${convPage}&limit=${convLimit}`, auth).then((d) => {
      setConversations(d.threads || []);
      setConvTotal(d.total || 0);
    });
  }, [accessToken, convPage, convLimit, auth]);

  const loadThread = useCallback(
    (id) => {
      if (!accessToken || !id) return;
      return apiFetch(`/api/admin/conversations/${id}`, auth).then((d) => setThreadDetail(d.thread || null));
    },
    [accessToken, auth]
  );

  const loadReports = useCallback(() => {
    if (!accessToken) return;
    const qs = new URLSearchParams({ page: String(reportPage), limit: String(reportLimit) });
    if (reportStatusFilter) qs.set("status", reportStatusFilter);
    return apiFetch(`/api/admin/reports?${qs.toString()}`, auth).then((d) => {
      setReports(d.reports || []);
      setReportTotal(d.total || 0);
    });
  }, [accessToken, reportPage, reportLimit, reportStatusFilter, auth]);

  const loadSettings = useCallback(() => {
    if (!accessToken) return;
    return apiFetch("/api/admin/settings", auth).then((d) => {
      setSettings(d.settings || null);
      if (d.settings) {
        setSettingsForm({
          commissionPercent: d.settings.commissionPercent,
          momoEnabled: d.settings.momoEnabled,
          stripeEnabled: d.settings.stripeEnabled,
          bankEnabled: d.settings.bankEnabled,
          listingPolicyNote: d.settings.listingPolicyNote || ""
        });
      }
    });
  }, [accessToken, auth]);

  const loadCategories = useCallback(() => {
    if (!accessToken) return;
    return apiFetch("/api/admin/categories", auth).then((d) => setCategoriesStat(d.categories || []));
  }, [accessToken, auth]);

  const loadSystemLog = useCallback(() => {
    if (!accessToken) return;
    return apiFetch("/api/admin/system-log", auth).then((d) => setSystemLog(d.entries || []));
  }, [accessToken, auth]);

  useEffect(() => {
    if (!accessToken) return;
    setLoading(true);
    setErr("");
    const p = (() => {
      if (tab === "dashboard") return loadDashboard();
      if (tab === "users") return loadUsers();
      if (tab === "listings") return loadListings();
      if (tab === "orders") return loadOrders();
      if (tab === "payments") return Promise.all([loadRevenue(), loadBalances()]).then(() => undefined);
      if (tab === "messages") return loadConversations();
      if (tab === "reports") return loadReports();
      if (tab === "categories") return loadCategories();
      if (tab === "logs") return loadSystemLog();
      if (tab === "settings") return loadSettings();
      return Promise.resolve();
    })();
    Promise.resolve(p).catch((ex) => setErr(ex.message || "Load failed"));
    Promise.resolve(p).finally(() => setLoading(false));
  }, [
    accessToken,
    tab,
    loadDashboard,
    loadUsers,
    loadListings,
    loadOrders,
    loadRevenue,
    loadBalances,
    loadConversations,
    loadReports,
    loadCategories,
    loadSystemLog,
    loadSettings
  ]);

  useEffect(() => {
    if (tab !== "messages" || !selectedThreadId) {
      setThreadDetail(null);
      return;
    }
    loadThread(selectedThreadId);
  }, [tab, selectedThreadId, loadThread]);

  useEffect(() => {
    if (!accessToken || tab !== "payments") return;
    setLoading(true);
    loadRevenue()
      .catch((ex) => setErr(ex.message || "Revenue load failed"))
      .finally(() => setLoading(false));
  }, [accessToken, tab, revDays, loadRevenue]);

  useEffect(() => {
    setAppliedSearch("");
    setHeaderSearch("");
  }, [tab]);

  if (!user || user.role !== "admin") {
    if (!accessToken) return h(Navigate, { to: "/login", replace: true, state: { from: "/admin" } });
    return h(
      "div",
      { className: "flex min-h-screen items-center justify-center bg-night-950 px-4 text-slate-200" },
      h("p", { className: "text-center" }, "You don’t have access to the admin area.")
    );
  }

  const applyHeaderSearch = (e) => {
    e?.preventDefault?.();
    const val = headerSearch.trim();
    setAppliedSearch(val);
    if (tab === "users") setUsersPage(1);
    if (tab === "listings") setListingsPage(1);
  };

  const patchUser = async (id, body) => {
    try {
      await apiFetch(`/api/admin/users/${id}`, { method: "PATCH", ...auth, json: body });
      await loadUsers();
      if (userSummary && userSummary.user.id === id) {
        const d = await apiFetch(`/api/admin/users/${id}/summary`, auth);
        setUserSummary(d);
      }
    } catch (ex) {
      await alert(ex.message || "Update failed", { variant: "error", title: "User" });
    }
  };

  const onUserAction = async (u, nextStatus) => {
    if (nextStatus === "banned") {
      const ok = await confirm(`Ban ${u.displayName || u.email || u.id}? They won’t be able to sign in.`, {
        title: "Ban user?",
        confirmLabel: "Ban"
      });
      if (!ok) return;
    }
    await patchUser(u.id, { accountStatus: nextStatus });
  };

  const approve = async (id) => {
    try {
      await apiFetch(`/api/admin/products/${id}/approve`, { method: "POST", ...auth, json: {} });
      setRejectId(null);
      setRejectReason("");
      await loadListings();
      await loadDashboard();
      toast("Listing approved", { variant: "success" });
    } catch (ex) {
      await alert(ex.message || "Approve failed", { variant: "error" });
    }
  };

  const submitReject = async () => {
    if (!rejectId) return;
    const reason = rejectReason.trim();
    if (reason.length < 1) {
      await alert("Add a short reason for the seller.", { variant: "warning", title: "Reason required" });
      return;
    }
    try {
      await apiFetch(`/api/admin/products/${rejectId}/reject`, { method: "POST", ...auth, json: { reason } });
      setRejectId(null);
      setRejectReason("");
      await loadListings();
      await loadDashboard();
      toast("Listing rejected", { variant: "success" });
    } catch (ex) {
      await alert(ex.message || "Reject failed", { variant: "error" });
    }
  };

  const delListing = async (id) => {
    const ok = await confirm("Delete this listing permanently?", { title: "Delete product", confirmLabel: "Delete" });
    if (!ok) return;
    try {
      await apiFetch(`/api/admin/products/${id}`, { method: "DELETE", ...auth });
      toast("Product removed", { variant: "success" });
      await loadListings();
      await loadDashboard();
    } catch (ex) {
      await alert(ex.message || "Delete failed", { variant: "error" });
    }
  };

  const toggleFlag = async (p) => {
    try {
      await apiFetch(`/api/admin/products/${p.id}`, { method: "PATCH", ...auth, json: { flagged: !p.flagged } });
      await loadListings();
    } catch (ex) {
      await alert(ex.message || "Update failed", { variant: "error" });
    }
  };

  const saveListingEdit = async () => {
    if (!editList) return;
    try {
      const price = Number(editPrice);
      if (!Number.isFinite(price) || price < 0) {
        await alert("Enter a valid price", { variant: "warning" });
        return;
      }
      await apiFetch(`/api/admin/products/${editList.id}`, { method: "PATCH", ...auth, json: { price } });
      setEditList(null);
      await loadListings();
      toast("Listing updated", { variant: "success" });
    } catch (ex) {
      await alert(ex.message || "Save failed", { variant: "error" });
    }
  };

  const openOrderModeration = (o) => {
    setModerateOrder(o);
    setOrdStatus(o.status);
    setOrdDispute(!!o.disputeOpen);
    setOrdNote(o.adminNote || "");
    setOrdRefund(o.refundStatus || "none");
  };

  const saveOrderModeration = async () => {
    if (!moderateOrder) return;
    try {
      await apiFetch(`/api/admin/orders/${moderateOrder.id}`, {
        method: "PATCH",
        ...auth,
        json: { status: ordStatus, disputeOpen: ordDispute, adminNote: ordNote, refundStatus: ordRefund }
      });
      toast("Order updated", { variant: "success" });
      setModerateOrder(null);
      await loadOrders();
    } catch (ex) {
      await alert(ex.message || "Update failed", { variant: "error" });
    }
  };

  const submitPasswordReset = async () => {
    if (!resetUserId) return;
    if (resetPassword.length < 8) {
      await alert("Password must be at least 8 characters.", { variant: "warning" });
      return;
    }
    try {
      await apiFetch(`/api/admin/users/${resetUserId}/reset-password`, {
        method: "POST",
        ...auth,
        json: { newPassword: resetPassword }
      });
      toast("Password updated", { variant: "success" });
      setResetUserId(null);
      setResetPassword("");
    } catch (ex) {
      await alert(ex.message || "Reset failed", { variant: "error" });
    }
  };

  const patchReportStatus = async (r, status) => {
    try {
      await apiFetch(`/api/admin/reports/${r.id}`, { method: "PATCH", ...auth, json: { status } });
      await loadReports();
      await loadDashboard();
    } catch (ex) {
      await alert(ex.message || "Update failed", { variant: "error" });
    }
  };

  const saveSettings = async () => {
    setSavingSettings(true);
    try {
      await apiFetch("/api/admin/settings", { method: "PATCH", ...auth, json: settingsForm });
      toast("Settings saved. New checkouts use the updated commission.", { variant: "success" });
      await loadSettings();
    } catch (ex) {
      await alert(ex.message || "Save failed", { variant: "error" });
    } finally {
      setSavingSettings(false);
    }
  };

  // dashboard aggregates
