                ]),
                h("div", { className: "rounded-xl bg-violet-500/10 px-2 py-2" }, [
                  h("p", { className: "text-[10px] uppercase text-violet-500" }, "Revenue"),
                  h("p", { className: "mt-0.5 font-display text-sm font-bold text-slate-900 dark:text-white" }, formatGhc(c.grossRevenue || 0))
                ])
              ])
            ])
          )
    )
  ]);

  const logsTab = h(f, { key: "logs" }, [
    h(
      GlassPanel,
      { className: "!p-0" },
      systemLog.length === 0
        ? h("p", { className: "p-6 text-sm text-slate-500" }, "No activity yet.")
        : h(
            "ul",
            { className: "divide-y divide-white/10" },
            systemLog.map((e, i) =>
              h(
                "li",
                {
                  key: i,
                  className: "flex items-start gap-3 px-4 py-3"
                },
                [
                  h(
                    "span",
                    {
                      className: `flex h-8 w-8 items-center justify-center rounded-2xl ${
                        e.tone === "danger"
                          ? "bg-rose-500/15 text-rose-400"
                          : e.tone === "warn"
                          ? "bg-amber-500/15 text-amber-400"
                          : e.tone === "success"
                          ? "bg-emerald-500/15 text-emerald-400"
                          : e.tone === "info"
                          ? "bg-sky-500/15 text-sky-400"
                          : "bg-slate-500/15 text-slate-400"
                      }`
                    },
                    h(
                      {
                        signup: UserPlus,
                        listing: Package,
                        order: ShoppingBag,
                        report: AlertTriangle
                      }[e.type] || Activity,
                      { className: "h-4 w-4" }
                    )
                  ),
                  h("div", { className: "min-w-0 flex-1" }, [
                    h("div", { className: "flex items-center justify-between gap-2" }, [
                      h("p", { className: "truncate text-sm text-slate-900 dark:text-white" }, e.label),
                      h("span", { className: "shrink-0 text-xs text-slate-400" }, relTime(e.at))
                    ]),
                    h("p", { className: "text-xs uppercase tracking-wide text-slate-500" }, e.type)
                  ])
                ]
              )
            )
          )
    )
  ]);

  const settingsTab = h(f, { key: "set" }, [
    h("div", { className: "grid grid-cols-1 gap-4 lg:grid-cols-2" }, [
      h(GlassPanel, { key: "com", className: "!p-5" }, [
        h("div", { className: "mb-3 flex items-center gap-2" }, [
          h(
            "span",
            { className: "flex h-9 w-9 items-center justify-center rounded-2xl bg-amber-500/15 text-amber-500" },
            h(DollarSign, { className: "h-5 w-5" })
          ),
          h("div", null, [
            h("h3", { className: "font-semibold text-slate-900 dark:text-white" }, "Commission Settings"),
            h("p", { className: "text-xs text-slate-500" }, "Applied to new checkouts. Existing orders keep stored fees.")
          ])
        ]),
        h(
          Field,
          { label: "Commission Rate (%)" },
          h(TextInput, {
            type: "number",
            min: 0,
            max: 100,
            step: "0.1",
            value: String(settingsForm.commissionPercent),
            onChange: (e) => setSettingsForm((s) => ({ ...s, commissionPercent: Number(e.target.value) }))
          })
        ),
        h(Button, { className: "mt-4", loading: savingSettings, onClick: saveSettings }, "Save changes")
      ]),
      h(GlassPanel, { key: "pay", className: "!p-5" }, [
        h("div", { className: "mb-3 flex items-center gap-2" }, [
          h(
            "span",
            { className: "flex h-9 w-9 items-center justify-center rounded-2xl bg-emerald-500/15 text-emerald-500" },
            h(DollarSign, { className: "h-5 w-5" })
          ),
          h("div", null, [
            h("h3", { className: "font-semibold text-slate-900 dark:text-white" }, "Payment Methods"),
            h("p", { className: "text-xs text-slate-500" }, "Enable channels shown during checkout.")
          ])
        ]),
        h("div", { className: "space-y-2" }, [
          [
            ["momoEnabled", "Mobile Money", "Pay via MTN / Telecel / AirtelTigo"],
            ["stripeEnabled", "Card Payments", "Stripe-powered card & Apple Pay"],
            ["bankEnabled", "Bank Transfer", "Manual bank transfer"]
          ].map(([key, title, sub]) =>
            h(
              "label",
              {
                key,
                className: "flex cursor-pointer items-center justify-between rounded-2xl border border-white/10 bg-white/40 p-3 text-sm dark:bg-white/5"
              },
              [
                h("div", null, [
                  h("p", { className: "font-medium text-slate-900 dark:text-white" }, title),
                  h("p", { className: "text-xs text-slate-500" }, sub)
                ]),
                h(
                  "span",
                  { className: "flex items-center gap-2" },
                  [
                    h(
                      Badge,
                      { tone: settingsForm[key] ? "success" : "neutral" },
                      settingsForm[key] ? "Enabled" : "Disabled"
                    ),
                    h("input", {
                      type: "checkbox",
                      checked: !!settingsForm[key],
                      onChange: (e) => setSettingsForm((s) => ({ ...s, [key]: e.target.checked }))
                    })
                  ]
                )
              ]
            )
          )
        ]),
        h(Button, { className: "mt-4", loading: savingSettings, onClick: saveSettings, variant: "ghost" }, "Save payment methods")
      ]),
      h(GlassPanel, { key: "rules", className: "!p-5 lg:col-span-2" }, [
        h("div", { className: "mb-3 flex items-center gap-2" }, [
          h(
            "span",
            { className: "flex h-9 w-9 items-center justify-center rounded-2xl bg-violet-500/15 text-violet-500" },
            h(ClipboardList, { className: "h-5 w-5" })
          ),
          h("div", null, [
            h("h3", { className: "font-semibold text-slate-900 dark:text-white" }, "Listing Rules & Policy"),
            h("p", { className: "text-xs text-slate-500" }, "Internal policy notes for moderation team.")
          ])
        ]),
        h(
          Field,
          { label: "Policy text" },
          h(TextArea, {
            value: settingsForm.listingPolicyNote,
            onChange: (e) => setSettingsForm((s) => ({ ...s, listingPolicyNote: e.target.value })),
            rows: 6,
            placeholder: "No illegal goods. No fake items. Respectful communication. etc."
          })
        ),
        h(Button, { className: "mt-3", loading: savingSettings, onClick: saveSettings }, "Save policy")
      ]),
      h(GlassPanel, { key: "status", className: "!p-5 lg:col-span-2" }, [
        h("div", { className: "mb-3 flex items-center gap-2" }, [
          h(
            "span",
            { className: "flex h-9 w-9 items-center justify-center rounded-2xl bg-sky-500/15 text-sky-500" },
            h(ShieldCheck, { className: "h-5 w-5" })
          ),
          h("div", null, [
            h("h3", { className: "font-semibold text-slate-900 dark:text-white" }, "System Status"),
            h("p", { className: "text-xs text-slate-500" }, "Live service indicators.")
          ])
        ]),
        h("div", { className: "grid grid-cols-1 gap-3 sm:grid-cols-2" }, [
          h(
            "div",
            { className: "flex items-center justify-between rounded-2xl border border-white/10 bg-white/40 p-3 dark:bg-white/5" },
            [h("span", { className: "text-sm" }, "API server"), h(Badge, { tone: "success" }, "Online")]
          ),
          h(
            "div",
            { className: "flex items-center justify-between rounded-2xl border border-white/10 bg-white/40 p-3 dark:bg-white/5" },
            [h("span", { className: "text-sm" }, "Database"), h(Badge, { tone: "success" }, "Connected")]
          ),
          h(
            "div",
            { className: "flex items-center justify-between rounded-2xl border border-white/10 bg-white/40 p-3 dark:bg-white/5" },
            [h("span", { className: "text-sm" }, "Platform commission"), h(Badge, { tone: "info" }, `${settings?.commissionPercent ?? settingsForm.commissionPercent}%`)]
          ),
          h(
            "div",
            { className: "flex items-center justify-between rounded-2xl border border-white/10 bg-white/40 p-3 dark:bg-white/5" },
            [
              h("span", { className: "text-sm" }, "Last settings update"),
              h("span", { className: "text-xs text-slate-500" }, settings?.updatedAt ? new Date(settings.updatedAt).toLocaleString() : "—")
            ]
          )
        ])
      ])
    ])
  ]);

  const tabContent = (() => {
    if (loading)
      return h(GlassPanel, { className: "!p-8" }, h("p", { className: "text-center text-sm text-slate-500" }, "Loading…"));
    if (tab === "dashboard") return dashboardTab;
    if (tab === "users") return usersTab;
    if (tab === "listings") return listingsTab;
    if (tab === "orders") return ordersTab;
    if (tab === "payments") return paymentsTab;
    if (tab === "messages") return messagesTab;
    if (tab === "reports") return reportsTab;
    if (tab === "categories") return categoriesTab;
    if (tab === "logs") return logsTab;
    if (tab === "settings") return settingsTab;
    return null;
  })();

  return h(
    "div",
    { className: "relative min-h-screen bg-slate-100 dark:bg-night-950 dark:bg-mesh-dark" },
    [
      sidebarOpen &&
        h("button", {
          key: "ov",
          type: "button",
          className: "fixed inset-0 z-30 bg-slate-950/50 backdrop-blur-sm lg:hidden",
          onClick: () => setSidebarOpen(false),
          "aria-label": "Close menu"
        }),
      sidebar,
      h("div", { key: "body", className: "lg:pl-72" }, [
        header,
        h("main", { key: "main", className: "mx-auto max-w-7xl px-4 py-6 sm:px-6" }, [
          err ? h(InlineNotice, { key: "e", variant: "error", className: "mb-4", onDismiss: () => setErr("") }, err) : null,
          tabContent
        ])
      ])
    ]
  );
}
